/**
 * @distilled.cloud/clerk — Clerk Backend API and Platform API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * specs). Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Clerk from "@distilled.cloud/clerk";
 *
 * const program = Effect.gen(function* () {
 *   const result = yield* Clerk.getUserList({});
 *   return result;
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   Clerk.CredentialsFromEnv,
 *   Clerk.ClerkProtocol,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 *
 * Platform API operations live under `Clerk.Platform`
 * (`Clerk.Platform.listApplications({})`) and take
 * `Clerk.PlatformCredentialsFromEnv` + `Clerk.ClerkPlatformProtocol` instead.
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  ClerkProtocol,
  ClerkPlatformProtocol,
  type ClerkOpError,
  type ClerkOpContext,
  type ClerkPlatformOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
export * from "./services/clerk.ts";
// The Platform API shares shape names with the Backend API (`User`,
// `JWTTemplate`, …), so it is a namespace rather than a flat re-export.
export * as Platform from "./services/platform.ts";
export {
  BadRequest,
  Conflict,
  Forbidden,
  NotFound,
  UnprocessableEntity,
} from "./services/clerk.ts";
